
"""
Sentinel - Data Storage Engine

Saves cleaned sales, cancellations, quarantine records,
and processing summaries to disk.
"""

import json
from pathlib import Path
import pandas as pd


PROJECT_ROOT = Path(__file__).resolve().parents[3]

PROCESSED_DIR = PROJECT_ROOT / "data" / "processed"
QUARANTINE_DIR = PROJECT_ROOT / "data" / "quarantine"
REPORTS_DIR = PROJECT_ROOT / "reports"


def save_pipeline_outputs(result: dict) -> dict:
    """Persist all outputs generated by the cleaning engine."""

    required_keys = {
        "cleaned",
        "cancellations",
        "quarantine",
        "summary",
    }

    if not isinstance(result, dict):
        raise TypeError("Pipeline result must be a dictionary.")

    missing_keys = required_keys - result.keys()

    if missing_keys:
        raise ValueError(f"Missing pipeline outputs: {missing_keys}")

    for key in ("cleaned", "cancellations", "quarantine"):
        if not isinstance(result[key], pd.DataFrame):
            raise TypeError(f"'{key}' must contain a DataFrame.")

    if not isinstance(result["summary"], dict):
        raise TypeError("'summary' must contain a dictionary.")

    # Create directories if they don't exist.
    PROCESSED_DIR.mkdir(parents=True, exist_ok=True)
    QUARANTINE_DIR.mkdir(parents=True, exist_ok=True)
    REPORTS_DIR.mkdir(parents=True, exist_ok=True)

    # Define output locations.
    output_paths = {
        "cleaned": PROCESSED_DIR / "cleaned_sales.csv",
        "cancellations": PROCESSED_DIR / "cancellations.csv",
        "quarantine": QUARANTINE_DIR / "quarantined_records.csv",
        "summary": REPORTS_DIR / "cleaning_summary.json",
    }

    # Save transaction datasets.
    result["cleaned"].to_csv(
        output_paths["cleaned"], index=False
    )

    result["cancellations"].to_csv(
        output_paths["cancellations"], index=False
    )

    result["quarantine"].to_csv(
        output_paths["quarantine"], index=False
    )

    # Save summary as JSON.
    with output_paths["summary"].open(
        "w", encoding="utf-8"
    ) as file:
        json.dump(result["summary"], file, indent=4)

    # Verify saved files.
    for name, path in output_paths.items():
        if not path.exists():
            raise IOError(f"Failed to save {name}: {path}")

    return {
        name: str(path)
        for name, path in output_paths.items()
    }


def main():
    from src.sentinel.ingestion.loader import load_workbook
    from src.sentinel.processing.cleaner import clean_data

    print("Loading source dataset...")
    dataframe = load_workbook()

    print("Cleaning transactions...")
    result = clean_data(dataframe)

    print("Saving pipeline outputs...")
    saved_files = save_pipeline_outputs(result)

    print("\nSENTINEL STORAGE SUMMARY")

    for name, path in saved_files.items():
        print(f"{name}: {path}")

    print("\nAll outputs saved successfully.")


if __name__ == "__main__":
    main()
